<?php
namespace App\Controllers; use App\Core\{Controller,Database}; use App\Services\LedgerService; class LedgerController extends Controller{public function index(){ $rows=Database::pdo()->query('SELECT * FROM ledger_entries ORDER BY id DESC LIMIT 100')->fetchAll();$this->view('ledger/index',['title'=>'دفتر کل غیرقابل حذف','rows'=>$rows]);} public function store(){ $this->requireCsrf();$lines=json_decode($_POST['lines']??'[]',true) ?: [];try{$id=(new LedgerService)->post($_POST['reference_type']??'manual',(int)($_POST['reference_id']??0),$_POST['description']??'',$lines);$this->json(['ok'=>true,'id'=>$id]);}catch(\Throwable $e){$this->json(['ok'=>false,'message'=>$e->getMessage()],422);}}}
